import type {ReactNode} from 'react';
import DocCardList from '@theme/DocCardList';
import {useCurrentSidebarSiblings} from '@docusaurus/plugin-content-docs/client';
import {useLocation} from '@docusaurus/router';

const trim = (s: string) => s.replace(/\/+$/, '');

/**
 * Card list for a product landing page.
 *
 * A bare `<DocCardList />` renders `useCurrentSidebarSiblings()`. Each product
 * is its own autogenerated sidebar rooted at the product directory, so the
 * landing page sits at the root as a *sibling* of the chapters rather than
 * their parent — and the plain card list therefore includes a card that links
 * back to the page you are already on. Drop that one and leave everything else
 * to the theme, so chapters keep their folder icon and "N items" subtitle.
 */
export default function ChapterCards(): ReactNode {
  const {pathname} = useLocation();
  const items = useCurrentSidebarSiblings().filter(
    (item) => !('href' in item && typeof item.href === 'string' && trim(item.href) === trim(pathname)),
  );
  return <DocCardList items={items} />;
}
